'use client';

import { useRouter } from 'next/navigation';
import { useState, type FormEvent } from 'react';
import { supabase } from '@/lib/supabase';

type SubmitState = 'idle' | 'loading' | 'error' | 'success';

const ORDA_SIGNUP_BACKGROUND = 'data:image/png;base64,';

export default function CustomerSignupPage() {
  const router = useRouter();

  const [username, setUsername] = useState('');
  const [phoneNumber, setPhoneNumber] = useState('');
  const [emailAddress, setEmailAddress] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [submitState, setSubmitState] = useState<SubmitState>('idle');
  const [message, setMessage] = useState('');

  function goToCustomerLogin() {
    router.push('/customer/login');

    window.setTimeout(() => {
      if (typeof window !== 'undefined' && window.location.pathname !== '/customer/login') {
        window.location.href = '/customer/login';
      }
    }, 120);
  }

  async function handleSignup(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    const cleanUsername = username.trim();
    const cleanPhone = phoneNumber.trim();
    const cleanEmail = emailAddress.trim().toLowerCase();

    if (!cleanUsername) {
      setSubmitState('error');
      setMessage('Enter your username.');
      return;
    }

    if (!cleanEmail) {
      setSubmitState('error');
      setMessage('Enter your email address.');
      return;
    }

    if (!password || password.length < 6) {
      setSubmitState('error');
      setMessage('Password must be at least 6 characters.');
      return;
    }

    setSubmitState('loading');
    setMessage('');

    const origin = typeof window !== 'undefined' ? window.location.origin : '';

    const { data, error } = await supabase.auth.signUp({
      email: cleanEmail,
      password,
      options: {
        emailRedirectTo: `${origin}/customer`,
        data: {
          role: 'customer',
          account_type: 'customer',
          username: cleanUsername,
          name: cleanUsername,
          phone: cleanPhone || null,
        },
      },
    });

    if (error) {
      setSubmitState('error');
      setMessage(error.message || 'Could not create account.');
      return;
    }

    if (data.user?.id) {
      await supabase.from('customers').upsert(
        {
          id: data.user.id,
          name: cleanUsername,
          email: cleanEmail,
          phone: cleanPhone || null,
          created_at: new Date().toISOString(),
        },
        { onConflict: 'id' }
      );
    }

    setSubmitState('success');

    if (data.session?.user) {
      router.replace('/customer');
      router.refresh();
      return;
    }

    setMessage('Check your email to confirm your account.');
  }

  return (
    <main className="page">
      <div className="blackFullScreen" aria-hidden="true" />

      <section className="signupFrame">
        <img
          src={ORDA_SIGNUP_BACKGROUND}
          alt="ORDA customer signup"
          className="backgroundImage"
          draggable={false}
        />

        <button
          type="button"
          className="logoHotspot"
          aria-label="Go to ORDA Discover"
          onClick={() => router.push('/discover')}
        />

        <form className="signupForm" onSubmit={handleSignup}>
          <div className="usernameCover">Username</div>

          <input
            className="field usernameField"
            type="text"
            autoComplete="username"
            placeholder="Enter username"
            value={username}
            onChange={(event) => setUsername(event.target.value)}
          />

          <input
            className="field phoneField"
            type="tel"
            autoComplete="tel"
            placeholder="(555) 123-4567"
            value={phoneNumber}
            onChange={(event) => setPhoneNumber(event.target.value)}
          />

          <input
            className="field emailField"
            type="email"
            autoComplete="email"
            placeholder="you@email.com"
            value={emailAddress}
            onChange={(event) => setEmailAddress(event.target.value)}
          />

          <div className="passwordWrap">
            <input
              className="field passwordField"
              type={showPassword ? 'text' : 'password'}
              autoComplete="new-password"
              placeholder="Create a password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
            />

            <button
              type="button"
              className="eyeButton"
              aria-label="Show password"
              onClick={() => setShowPassword((value) => !value)}
            />
          </div>

          {message ? <div className={`message ${submitState === 'error' ? 'error' : 'success'}`}>{message}</div> : null}

          <button type="submit" className="submitButton" disabled={submitState === 'loading'}>
            <span className="submitText">
              {submitState === 'loading' ? 'Creating Account...' : 'Create Your Free Account'}
            </span>
            <span className="submitArrow">→</span>
          </button>
        </form>

        <button type="button" className="visibleLoginButton" onClick={goToCustomerLogin}>
          <strong>Already have an account?</strong>
          <span>Log in →</span>
        </button>
      </section>

      <style jsx global>{`
        html,
        body,
        body > div {
          margin: 0 !important;
          padding: 0 !important;
          min-width: 100% !important;
          min-height: 100% !important;
          background: #010207 !important;
          background-color: #010207 !important;
          overflow-x: hidden !important;
        }

        body {
          color: #ffffff !important;
        }

        * {
          box-sizing: border-box;
        }

        input,
        button {
          font: inherit;
        }
      `}</style>

      <style jsx>{`
        .page {
          position: relative;
          width: 100%;
          min-height: 100vh;
          margin: 0;
          padding: 0;
          background: #010207;
          background-color: #010207;
          overflow-x: hidden;
          overflow-y: auto;
          display: flex;
          justify-content: center;
          align-items: flex-start;
          font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
          isolation: isolate;
        }

        .blackFullScreen {
          position: fixed;
          inset: 0;
          z-index: 0;
          background: #010207;
          background-color: #010207;
          pointer-events: none;
        }

        .signupFrame {
          position: relative;
          z-index: 1;
          width: min(100vw, 1024px);
          aspect-ratio: 1024 / 1536;
          flex: 0 0 auto;
          overflow: hidden;
          background: #010207;
          background-color: #010207;
        }

        .backgroundImage {
          position: absolute;
          inset: 0;
          z-index: 1;
          width: 100%;
          height: 100%;
          display: block;
          object-fit: cover;
          background: #010207;
          background-color: #010207;
          user-select: none;
          pointer-events: none;
        }

        .logoHotspot {
          position: absolute;
          z-index: 20;
          left: 5.4%;
          top: 2.8%;
          width: 26%;
          height: 7.2%;
          display: block;
          border: 0;
          background: transparent;
          cursor: pointer;
          padding: 0;
        }

        .signupForm {
          position: absolute;
          z-index: 150;
          left: 56.45%;
          top: 30.58%;
          width: 35.3%;
          height: 43.4%;
          pointer-events: auto;
        }

        .usernameCover {
          position: absolute;
          left: -0.3%;
          top: -0.45%;
          width: 45%;
          height: 28px;
          display: flex;
          align-items: center;
          color: #fff;
          background: #07060b;
          font-size: clamp(13px, 1.55vw, 16px);
          font-weight: 900;
          line-height: 1;
        }

        .field {
          position: absolute;
          z-index: 160;
          left: 0;
          width: 100%;
          height: clamp(50px, 6.84vw, 70px);
          border-radius: clamp(13px, 1.45vw, 16px);
          border: 1px solid rgba(255, 255, 255, 0.24);
          background: rgba(8, 8, 15, 0.94);
          color: #fff;
          outline: none;
          padding: 0 18px 0 clamp(48px, 5.7vw, 60px);
          font-size: clamp(14px, 1.65vw, 18px);
          font-weight: 600;
          letter-spacing: -0.02em;
          box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
        }

        .field::placeholder {
          color: rgba(255, 255, 255, 0.86);
        }

        .field:focus {
          border-color: rgba(255, 45, 149, 0.9);
          box-shadow:
            0 0 0 4px rgba(255, 45, 149, 0.13),
            0 0 25px rgba(255, 45, 149, 0.18);
        }

        .usernameField { top: 4.93%; }
        .phoneField { top: 25.23%; }
        .emailField { top: 45.55%; }

        .passwordWrap {
          position: absolute;
          z-index: 170;
          left: 0;
          top: 65.75%;
          width: 100%;
        }

        .passwordField {
          position: relative;
          top: 0;
          padding-right: 58px;
        }

        .eyeButton {
          position: absolute;
          z-index: 180;
          top: 50%;
          right: 3%;
          width: clamp(31px, 4.4vw, 43px);
          height: clamp(31px, 4.4vw, 43px);
          transform: translateY(-50%);
          border: 0;
          border-radius: 999px;
          background: transparent;
          cursor: pointer;
          padding: 0;
        }

        .submitButton {
          position: absolute;
          z-index: 190;
          left: 0;
          top: 85.2%;
          width: 100%;
          height: clamp(62px, 7.8vw, 80px);
          border: 0;
          border-radius: clamp(18px, 2vw, 24px);
          background:
            linear-gradient(180deg, rgba(255, 99, 190, 0.98) 0%, rgba(255, 34, 145, 1) 42%, rgba(255, 10, 120, 1) 100%);
          color: #fff;
          cursor: pointer;
          font-size: clamp(13px, 1.55vw, 16px);
          font-weight: 1000;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 14px;
          padding: 0;
          opacity: 1;
          box-shadow:
            0 0 18px rgba(255, 0, 128, 0.78),
            0 0 38px rgba(255, 0, 128, 0.46),
            inset 0 2px 0 rgba(255, 255, 255, 0.36),
            inset 0 -8px 18px rgba(130, 0, 70, 0.3);
        }

        .submitButton:disabled {
          cursor: not-allowed;
          opacity: 0.82;
        }

        .submitText {
          position: relative;
          z-index: 2;
          color: #ffffff;
          font-size: clamp(15px, 1.6vw, 18px);
          font-weight: 1000;
          letter-spacing: -0.03em;
          line-height: 1;
          text-shadow: 0 2px 10px rgba(0, 0, 0, 0.22);
        }

        .submitArrow {
          position: relative;
          z-index: 2;
          width: 34px;
          height: 34px;
          border-radius: 999px;
          background: rgba(255, 255, 255, 0.96);
          color: #ff0a78;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 20px;
          font-weight: 1000;
          line-height: 1;
          box-shadow: 0 0 16px rgba(255, 255, 255, 0.32);
        }

        .visibleLoginButton {
          position: absolute;
          z-index: 200;
          left: 5.6%;
          bottom: 1.7%;
          width: 88.8%;
          height: 6.45%;
          border-radius: clamp(20px, 3vw, 32px);
          border: 1px solid rgba(255, 45, 149, 0.36);
          background: rgba(0, 0, 0, 0.72);
          display: flex;
          align-items: center;
          justify-content: center;
          gap: clamp(24px, 4vw, 54px);
          color: #ffffff;
          font-size: clamp(18px, 2.4vw, 30px);
          font-weight: 1000;
          cursor: pointer;
          text-decoration: none;
          pointer-events: auto;
          padding: 0;
          box-shadow:
            0 0 18px rgba(255, 45, 149, 0.12),
            inset 0 1px 0 rgba(255, 255, 255, 0.05);
          -webkit-tap-highlight-color: rgba(255, 45, 149, 0.18);
        }

        .visibleLoginButton strong {
          color: #ffffff;
          font-weight: 1000;
        }

        .visibleLoginButton span {
          color: #ff2d95;
          font-weight: 1000;
        }

        .visibleLoginButton:hover {
          border-color: rgba(255, 45, 149, 0.75);
          box-shadow: 0 0 28px rgba(255, 45, 149, 0.28);
        }

        .message {
          position: absolute;
          left: 0;
          right: 0;
          top: 97.4%;
          min-height: 38px;
          border-radius: 14px;
          padding: 10px 12px;
          text-align: center;
          color: #fff;
          font-size: 13px;
          font-weight: 900;
          backdrop-filter: blur(12px);
        }

        .message.error {
          background: rgba(255, 59, 48, 0.25);
          border: 1px solid rgba(255, 59, 48, 0.38);
        }

        .message.success {
          background: rgba(52, 199, 89, 0.22);
          border: 1px solid rgba(52, 199, 89, 0.34);
        }

        @media (max-width: 760px) {
          .page {
            align-items: flex-start;
            overflow-x: hidden;
            overflow-y: auto;
          }

          .signupFrame {
            width: 100vw;
            max-width: 100vw;
            min-height: auto;
            aspect-ratio: 1024 / 1536;
            overflow: hidden;
          }

          .backgroundImage {
            width: 100%;
            height: 100%;
            object-fit: cover;
            object-position: center top;
          }

          .signupForm {
            z-index: 150;
            left: 56.45%;
            top: 30.58%;
            width: 35.3%;
            height: 43.4%;
            pointer-events: auto;
          }

          .usernameCover {
            top: -0.45%;
            height: 2.2vw;
            background: #07060b;
            font-size: 1.55vw;
          }

          .field {
            z-index: 160;
            height: 6.84vw;
            min-height: 0;
            border-radius: 1.55vw;
            padding: 0 1.7vw 0 5.7vw;
            font-size: 1.65vw;
            pointer-events: auto;
          }

          .passwordWrap {
            z-index: 170;
          }

          .passwordField {
            padding-right: 5.7vw;
          }

          .eyeButton {
            z-index: 180;
            width: 4.4vw;
            height: 4.4vw;
            pointer-events: auto;
          }

          .submitButton {
            z-index: 190;
            height: 7.8vw;
            border-radius: 2vw;
            pointer-events: auto;
          }

          .submitText {
            font-size: 1.6vw;
          }

          .submitArrow {
            width: 3.5vw;
            height: 3.5vw;
            font-size: 2vw;
          }

          .visibleLoginButton {
            z-index: 200;
            left: 5.6%;
            bottom: 1.7%;
            width: 88.8%;
            height: 6.45%;
            gap: 4vw;
            font-size: 2.4vw;
            pointer-events: auto;
          }

          .message {
            top: 97.4%;
            min-height: 3.8vw;
            padding: 1vw 1.2vw;
            border-radius: 1.4vw;
            font-size: 1.35vw;
          }
        }

        @media (max-width: 520px) {
          .visibleLoginButton {
            left: 5.5%;
            bottom: 1.65%;
            width: 89%;
            height: 6.55%;
            gap: 14px;
            font-size: 18px;
          }

          .field {
            height: 7vw;
            font-size: 1.9vw;
          }

          .usernameCover {
            font-size: 1.9vw;
          }

          .submitText {
            font-size: 1.85vw;
          }
        }
      `}</style>
    </main>
  );
}
